<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --gateway</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 192.168.100.1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
