<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --network-alias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
